"use strict";(globalThis.webpackChunkjc_community_site=globalThis.webpackChunkjc_community_site||[]).push([[83334],{56744(e,t,n){n.r(t),n.d(t,{assets:()=>h,contentTitle:()=>r,default:()=>c,frontMatter:()=>s,metadata:()=>a,toc:()=>l});const a=JSON.parse('{"id":"general/dynamic-it-strategy-what-is-it-amp-how-to-do-it-ft-ken-russell","title":"Dynamic It Strategy What Is It Amp How To Do It Ft Ken Russell","description":"By urvashi","source":"@site/docs/general/dynamic-it-strategy-what-is-it-amp-how-to-do-it-ft-ken-russell.md","sourceDirName":"general","slug":"/general/dynamic-it-strategy-what-is-it-amp-how-to-do-it-ft-ken-russell","permalink":"/jc-community-archive/general/dynamic-it-strategy-what-is-it-amp-how-to-do-it-ft-ken-russell","draft":false,"unlisted":false,"tags":[],"version":"current","frontMatter":{"title":"Dynamic It Strategy What Is It Amp How To Do It Ft Ken Russell","description":"By urvashi"},"sidebar":"docs","previous":{"title":"Dynamic Groups Preview","permalink":"/jc-community-archive/general/dynamic-groups-preview"},"next":{"title":"Dynatrace Sso Saml Message Not Signed","permalink":"/jc-community-archive/general/dynatrace-sso-saml-message-not-signed"}}');var o=n(74848),i=n(28453);const s={title:"Dynamic It Strategy What Is It Amp How To Do It Ft Ken Russell",description:"By urvashi"},r=void 0,h={},l=[{value:"Overview",id:"overview",level:2},{value:"Transcript",id:"transcript",level:2},{value:"Introduction",id:"introduction",level:3},{value:"IT Strategy - Then &amp; Now",id:"it-strategy---then--now",level:3},{value:"IT Strategy - Getting Started",id:"it-strategy---getting-started",level:3},{value:"Dynamic/Kinetic IT Strategy",id:"dynamickinetic-it-strategy",level:3},{value:"Q&amp;A: Staffing Trends",id:"qa-staffing-trends",level:3},{value:"Wrap Up",id:"wrap-up",level:3}];function d(e){const t={a:"a",h2:"h2",h3:"h3",li:"li",ol:"ol",p:"p",strong:"strong",ul:"ul",...(0,i.R)(),...e.components};return(0,o.jsxs)(o.Fragment,{children:[(0,o.jsxs)(t.p,{children:["This is an edited transcript of the ",(0,o.jsx)(t.a,{href:"https://www.youtube.com/watch?v=R8XoR3Jtcak",children:"02.16.24 IT Hour"})]}),"\n",(0,o.jsx)(t.h2,{id:"overview",children:"Overview"}),"\n",(0,o.jsxs)(t.ul,{children:["\n",(0,o.jsxs)(t.li,{children:[(0,o.jsx)(t.strong,{children:"Ken Russell"}),", Chief Information and Innovation Officer at the New College Institute talks about the importance of and ways to develop an IT Strategy"]}),"\n",(0,o.jsxs)(t.li,{children:[(0,o.jsx)(t.strong,{children:"Becky Scott"}),", Head of Community at JumpCloud weighs in to moderate the discussion and Q&A, and adds her perspective to Ken\u2019s forecasts and comments on trends."]}),"\n"]}),"\n",(0,o.jsx)(t.h2,{id:"transcript",children:"Transcript"}),"\n",(0,o.jsx)(t.h3,{id:"introduction",children:"Introduction"}),"\n",(0,o.jsxs)(t.p,{children:[(0,o.jsx)(t.strong,{children:"Becky:"})," Ken, for those who haven\u2019t seen you on the show yet, tell us who you are and why you\u2019re here.\xa0"]}),"\n",(0,o.jsxs)(t.p,{children:[(0,o.jsx)(t.strong,{children:"Ken:"})," I\u2019m the Chief Information and Innovation officer for New College Institute which is a state agency in the Commonwealth of Virginia, and what we do there is work with all the universities and all the K-12s as a higher education learning center for the commonwealth. We\u2019re one of five and my particular role on any given day is either the Chief Information Officer, normally, where I talk about technology issues, or I\u2019m the Chief Innovation Officer where I\u2019m helping develop new methods for leading the next generation of educational tools and technologies.\xa0"]}),"\n",(0,o.jsxs)(t.p,{children:[(0,o.jsx)(t.strong,{children:"Becky:"})," We are going to talk about IT Strategy today, because we talk a lot about tactical stuff, how to deploy JumpCloud, how to use it, and talk about our product. It\u2019s hard to talk about it enough because we\u2019re so in the thick of things and in the weeds, so let\u2019s take the time to step back and talk about why we need strategy, why it\u2019s important, and why we should bother."]}),"\n",(0,o.jsx)(t.h3,{id:"it-strategy---then--now",children:"IT Strategy - Then & Now"}),"\n",(0,o.jsxs)(t.p,{children:[(0,o.jsx)(t.strong,{children:"Ken:"})," The hard questions straight away. It\u2019s funny I\u2019m part of these CIO groups and something that people don\u2019t usually talk about at least any more is strategy. Particularly IT Strategy. It used to be that the strategy process almost totally excluded IT. We were just sort of told, \u201cThis is the strategy. This is what the business or the organization is going to do.\u201d The reason businesses do it is because if they\u2019re a large publicly traded company they\u2019re compelled to do so. It\u2019s part of their numbers that they have to report - their activities, their growth plans, etc.\xa0"]}),"\n",(0,o.jsx)(t.p,{children:"The reason I think it\u2019s finally getting in the game - There\u2019s a couple of stories here. One comes from Jamie Dimon, the CEO of Chase. I\u2019m paraphrasing but he said all organizations are IT organizations. So you can no longer have any technophobes, and I think that\u2019s true. I think the days are long gone that you could be in an organization and not be at least conversant in IT. The other thing that happened is the pandemic which finally put us at the table at these discussions.\xa0"}),"\n",(0,o.jsx)(t.p,{children:"So when the organization is having a strategy session, they get together and talk about the plan for the future and how to get there. Now IT is a big part of that. But it\u2019s like a dog that\u2019s trying to catch its tail. It finally does catch it and then doesn\u2019t know what to do with it. One of the biggest problems that we had from an IT perspective was adoption of technologies. If you think about it, we were ready in 2020 with remote technologies and capabilities but it was hard to get the business to accept that we were ready. And then suddenly everyone was working remotely so we were finally at the table.\xa0"}),"\n",(0,o.jsx)(t.p,{children:"But are we ready to talk about how we create a plan as well? Do we have an IT plan? And an organization plan? How does that work? I can answer those but I want to stop here for a moment and let that sink in.\xa0"}),"\n",(0,o.jsxs)(t.p,{children:[(0,o.jsx)(t.strong,{children:"Becky:"})," I think part of the thing is that all these conversations are happening at the executive level and they tend to forget to ask those who are down at the tactical level what they\u2019re doing. It doesn\u2019t happen all the time, we do sometimes have executives that talk to us about what we need and what we\u2019re doing and ask us to contribute to the plan, but I\u2019ve seen in really big organizations that they make their plans and don\u2019t talk to people.\xa0"]}),"\n",(0,o.jsx)(t.p,{children:"But we\u2019re dealing with smaller businesses that maybe don\u2019t have a ton of people. So it\u2019s on these people here in the audience to kind of do it all - the tactical stuff and the strategy. It\u2019s actually harder to pull away and step back when you\u2019re right in the middle of things and think about what needs to be done for the next three to five years. How do you recommend that people take a step back and strategize? How do you communicate it with the C suite?\xa0"}),"\n",(0,o.jsx)(t.h3,{id:"it-strategy---getting-started",children:"IT Strategy - Getting Started"}),"\n",(0,o.jsxs)(t.p,{children:[(0,o.jsx)(t.strong,{children:"Ken:"})," You have to show the value of IT and the best way to do that is to start your IT strategy plan. You have to have your own IT plan and it has to roll up to the organization\u2019s strategy plan. So 2-5 years is a normal horizon to be looking at, anything less is more of a tactical plan.\xa0"]}),"\n",(0,o.jsx)(t.p,{children:"A good example of a strategy would be cost containment. Or revenue growth. When the organization is in cost containment mode, most of your efforts are around saving money or cutting costs, and that\u2019s a very popular strategy. But once in a while, particularly in acquisition mode, you have a bucket of money for acquiring stuff. So modalities may be different based on the organization\u2019s current direction.\xa0"}),"\n",(0,o.jsx)(t.p,{children:"But here\u2019s the issue. If you build your IT Strategy in February when the organization is focused on cost containment, you\u2019ll be focused on cutting costs - renegotiating contracts, service level agreements, and things like that. But let\u2019s say in April or May some external force like an acquisition or a tragedy changes the company\u2019s direction, you\u2019ll have to accommodate the changes as best you can. You have to pay attention and listen to what the organization is doing and change as quickly.\xa0"}),"\n",(0,o.jsx)(t.p,{children:"What you can\u2019t have is what we used to have - a big book that you do every September or October. Work on it for a few days, put it on the shelf and bring it down next September or October. You can\u2019t do that anymore.\xa0"}),"\n",(0,o.jsx)(t.p,{children:"But it also reminds me of when our CEO would fly and pick up the airline magazine and say \u201cHey let\u2019s do this\u201d. That\u2019s when you can say \u201cIt\u2019s not in our strategy plan.\u201d Then you can\u2019t really have the CEO go against you because they\u2019ve already approved the plan. They\u2019ll continue to try but you have something in your arsenal that says \u201cWe have a line in there to evaluate new technologies, but we\u2019re not going to implement.\u201d"}),"\n",(0,o.jsxs)(t.p,{children:[(0,o.jsx)(t.strong,{children:"Becky"}),": What do you do with CEOs that insist on it anyway?"]}),"\n",(0,o.jsxs)(t.p,{children:[(0,o.jsx)(t.strong,{children:"Ken"}),": At the end of the day if it comes down to a battle of wills you have to defer to the CEO because that\u2019s their job. These folks are writing the checks. But I think our voice is stronger now, post pandemic."]}),"\n",(0,o.jsx)(t.h3,{id:"dynamickinetic-it-strategy",children:"Dynamic/Kinetic IT Strategy"}),"\n",(0,o.jsxs)(t.p,{children:[(0,o.jsx)(t.strong,{children:"Ken:"})," We decided to make strategies more dynamic, because it really is a dynamic thing, where things change every single day. We actually call it Kinetic Strategy, based on the physics of it all. Most strategies are potential until they become kinetic or in action. So we came up with an approach that has four phases:\xa0"]}),"\n",(0,o.jsxs)(t.ol,{children:["\n",(0,o.jsxs)(t.li,{children:[(0,o.jsx)(t.strong,{children:"Approach"})," - This is the process of listening and paying attention to what\u2019s going on in your organization. Making sure you\u2019re not just focused on the IT aspects of the business, but the overall business. If you work for a large publicly traded company you need to take time to read the reports for the stock exchange and things like that. If you work for a small private company, read the tax documents. Make sure you\u2019re connected in ways that maybe you haven\u2019t been before. Because it\u2019s not just about how many servers you need and why."]}),"\n",(0,o.jsxs)(t.li,{children:[(0,o.jsx)(t.strong,{children:"Initiation"})," - This is what some folks will call business requirements gathering. Taking the time to write down the things you\u2019ve heard and shape them in a way that matters for the organization."]}),"\n",(0,o.jsxs)(t.li,{children:[(0,o.jsx)(t.strong,{children:"Fusion"})," - This is where you blend it all together. You put it all down and start prioritizing. A lot of folks will have business requirements that they\u2019ll use to get business objectives and what we call gap objectives. Gap objectives are those things that you know are important but you don\u2019t know why, but you have an intuition about it. Some people call those future needs."]}),"\n",(0,o.jsxs)(t.li,{children:[(0,o.jsx)(t.strong,{children:"Measures"})," - Notice that they\u2019re not metrics. Measures and metrics are two different things. You need measures before you can get to metrics. Measures are things like \u201ccustomer satisfaction\u201d or \u201cserver uptime\u201d. Metrics is the math, like 16% less or a thousand more of that. Measures will help you evaluate your progress against the larger organizational strategic plan."]}),"\n"]}),"\n",(0,o.jsx)(t.p,{children:"Strategies are designed to improve what is right. So a lot of folks will get stuck when they\u2019re in the planning process. They won\u2019t know what to do next. But there\u2019s always something you can do to make it better and the best place to look for that stuff is to get different perspectives. What I do, and a lot of my CIO colleagues do is what we call a walkabout. They\u2019ll walk among everybody and just listen. But \u201clisten\u201d is really an acronym that I talk about a lot:\xa0"}),"\n",(0,o.jsxs)(t.ul,{children:["\n",(0,o.jsxs)(t.li,{children:[(0,o.jsx)(t.strong,{children:"L - Learn"})," as much as you can about your organization. Take the time and pay attention not just to what executives are saying but everyone else also - the partners, the vendors, the guy that started yesterday, the intern, whoever it might be. Listen and learn."]}),"\n",(0,o.jsxs)(t.li,{children:[(0,o.jsx)(t.strong,{children:"I - Interpret"})," what you\u2019re hearing in a way that\u2019s meaningful for the organization. That\u2019s why strategy plans are so important. Because it\u2019s where you actually communicate that interpretation."]}),"\n",(0,o.jsxs)(t.li,{children:[(0,o.jsx)(t.strong,{children:"S - Shape"})," what you\u2019ve listened to, learned, and interpreted into how you can actually make it work for the organization."]}),"\n",(0,o.jsxs)(t.li,{children:[(0,o.jsx)(t.strong,{children:"T - Transform"})," what you\u2019ve listened to, learned, interpreted, and shaped in a way that\u2019s meaningful to the organization. Put down how you can transform the organization with this knowledge."]}),"\n",(0,o.jsxs)(t.li,{children:[(0,o.jsx)(t.strong,{children:"E - Evolve"})," into the organization that you need to be, not what you want to be, based on all that learning and interpreting and knowledge that you\u2019ve gained."]}),"\n",(0,o.jsxs)(t.li,{children:[(0,o.jsx)(t.strong,{children:"N - Nurture"})," the organization through that evolution. A really hot term these past few years has been transformation. If you\u2019re transforming you\u2019re taking a turn in a different direction. So if you don\u2019t take the time to evolve and nurture, the transformation will fail."]}),"\n"]}),"\n",(0,o.jsx)(t.h3,{id:"qa-staffing-trends",children:"Q&A: Staffing Trends"}),"\n",(0,o.jsxs)(t.p,{children:[(0,o.jsx)(t.strong,{children:"Becky"}),": ",(0,o.jsx)(t.strong,{children:"Brandon has a question about how you feel about staffing trends in IT. Do companies tend to over or under staff?"})]}),"\n",(0,o.jsxs)(t.p,{children:[(0,o.jsx)(t.strong,{children:"Ken:"})," The trend I\u2019m seeing that I don\u2019t like is that they tend to use contractors more than full time employees. I think that\u2019s understandable because it makes it more flexible but it also takes away the intellectual capital. I think HR is challenging staff to be small and nimble to the point of being dangerous. I think that\u2019s the challenge in most organizations. I think it\u2019s important to keep intellectual capital inside the organization.\xa0"]}),"\n",(0,o.jsx)(t.p,{children:(0,o.jsx)(t.strong,{children:"Becky: But sometimes when companies are really small, when they don\u2019t have the knowledge internally, doesn\u2019t it come in handy to find a trusted partner who can scale for you until you\u2019re big enough to be able to hire internally?"})}),"\n",(0,o.jsxs)(t.p,{children:[(0,o.jsx)(t.strong,{children:"Ken:"})," That is a strategy - to develop trusted partnerships. But there\u2019s a difference between vendors and partners. Sometimes you need a vendor to buy devices, or copies of something. You get the cheapest price because it\u2019s all the same. But when you need someone to go through the muck with you, configure a data center or something like that, you want a partner, not a vendor. The difference is that a partner will answer a call at 2 am on a Saturday morning and help you through the issue. A vendor may not. So take the time to develop those trusted partnerships.\xa0"]}),"\n",(0,o.jsx)(t.p,{children:(0,o.jsx)(t.strong,{children:"Becky: Brandon wants to know how you choose when to use an MSP or build that knowledge in house."})}),"\n",(0,o.jsxs)(t.p,{children:[(0,o.jsx)(t.strong,{children:"Ken:"})," It depends on the project and your existing staffing level. When a project comes along and you don\u2019t have the staff to do it and it\u2019s hard to get full time staff on board, you do have to go to an MSP. The other reason is expertise. It\u2019s hard to maintain expertise at a particular level for projects that start and then finish and go away.\xa0"]}),"\n",(0,o.jsxs)(t.p,{children:[(0,o.jsx)(t.strong,{children:"Becky"}),": ",(0,o.jsx)(t.strong,{children:"Brandon wants to know how you see trends in regards to employees moving companies more and more as it\u2019s becoming less advantageous to stay with the company forever."})," I mean that is something we see right, get a raise or a better title and they job hop.\xa0"]}),"\n",(0,o.jsxs)(t.p,{children:[(0,o.jsx)(t.strong,{children:"Ken"}),": I can tell you a very real story, with very real companies about poaching. Let\u2019s say there\u2019s two large retail companies and a large bank in the same city. One retail company would bring in young talent because they were cheap, get them trained, get them all the certifications so that six or eight months later they\u2019re really valuable but still being paid as if they\u2019re new hires. Then the other retail company would come poach them because they were already trained.\xa0"]}),"\n",(0,o.jsx)(t.p,{children:"Finally the two CIOs of the retail companies met and agreed that the poacher company wouldn\u2019t try to hire people from the other retail company for two years. If someone wanted to apply that would be fine but they would hit a wall of resistance if they went over. But in a free market, guess what happened? The bank took them all by paying them way too much money.\xa0"}),"\n",(0,o.jsx)(t.p,{children:"So the executive saw people leaving for an extra dollar, but they also saw people coming back. Six months later at the bank those employees realized that they had it good at the retail company. Maybe they weren\u2019t getting paid as much but they were given a lot of training and nurturing. Some organizations may pay you more money but they may not nurture you.\xa0"}),"\n",(0,o.jsx)(t.p,{children:"When we talk about employees moving, it\u2019s about at what cost. What price are they willing to pay to get that extra dollar? Are they going to work extra hours, drive farther, be in a more stressful work environment? All of these things have to be thought about before moving, not just the pay.\xa0"}),"\n",(0,o.jsx)(t.h3,{id:"wrap-up",children:"Wrap Up"}),"\n",(0,o.jsxs)(t.p,{children:[(0,o.jsx)(t.strong,{children:"Becky"}),": What I\u2019m seeing in the last 4-6 months is that it\u2019s getting harder to job hop because of all the tech layoffs. I saw a statistic saying there were fewer tech layoffs even though it seems like a lot right now, but I\u2019m seeing a ton of people out in the job market now. So it\u2019s harder to job hop because so many people were dumped out from big companies.\xa0"]}),"\n",(0,o.jsx)(t.p,{children:"And the pay is starting to shrink a bit on those same jobs from a year or two\xa0 ago, during the pandemic when they were paying really well. So we\u2019re actually seeing a different trend that it\u2019s getting harder to job hop. I think poaching could still happen but employers are seeing hundreds and hundreds of people applying because that\u2019s how many people want the open jobs, even though they\u2019re paying less.\xa0"}),"\n",(0,o.jsxs)(t.p,{children:[(0,o.jsx)(t.strong,{children:"Ken"}),": Yeah marketing pressures have a lot to do with it. The pendulum swung to the other side after the pay increases right after the pandemic. Now it\u2019s coming back. I think a lot of folks ramped up last year thinking there will be a huge need for IT talent and then realizing that the projections were off. So companies do what companies do which is to act in their best interest.\xa0"]}),"\n",(0,o.jsx)(t.p,{children:"The best way I\u2019ve found in my career to manage this is to be unique and valuable. Particularly IT Admin folks. I think there\u2019s always going to be a value for IT Admin folks. So don\u2019t get discouraged.\xa0"}),"\n",(0,o.jsxs)(t.p,{children:[(0,o.jsx)(t.strong,{children:"Becky"}),": Thank you all for joining and we hope you have a great weekend. See you next Friday!"]})]})}function c(e={}){const{wrapper:t}={...(0,i.R)(),...e.components};return t?(0,o.jsx)(t,{...e,children:(0,o.jsx)(d,{...e})}):d(e)}},28453(e,t,n){n.d(t,{R:()=>s,x:()=>r});var a=n(96540);const o={},i=a.createContext(o);function s(e){const t=a.useContext(i);return a.useMemo(function(){return"function"==typeof e?e(t):{...t,...e}},[t,e])}function r(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(o):e.components||o:s(e.components),a.createElement(i.Provider,{value:t},e.children)}}}]);